import { chooseProfile, choiceFor, isPhaseStep, type FeaturePhaseChoices, type PhaseChoiceStore } from '../src/agent/session/phase-choices'

function fakeStore(seed: FeaturePhaseChoices = {}): PhaseChoiceStore & { saved: FeaturePhaseChoices[] } {
  let current = seed
  const saved: FeaturePhaseChoices[] = []
