export function shouldApplyPhaseChoice(status: SessionStatus, current: ModelProfile, resolution: PhaseProfile): boolean {
  if (underWay(status)) return false
  if (resolution.kind !== 'ok') return false
  return !sameModelProfile(current, resolution.profile)
}

